create extension if not exists pgcrypto;
create table public.weddings (id uuid primary key default gen_random_uuid(),owner_user_id uuid not null references auth.users(id) on delete cascade,partner_one_name text not null,partner_two_name text not null,wedding_date date,title text not null,slug text not null unique check (slug ~ '^[a-z0-9-]+$'),welcome_message text not null default 'See where our story has taken us and help choose where we go next.',accent_color text not null default 'antique_gold',background_theme text not null default 'ivory',hero_image_url text,status text not null default 'active' check(status in ('draft','active','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.story_locations (id uuid primary key default gen_random_uuid(),wedding_id uuid not null references public.weddings(id) on delete cascade,location_name text not null,latitude double precision not null,longitude double precision not null,mapbox_place_id text,story_type text not null,title text not null,description text not null,event_date date,image_url text,sort_order integer not null default 0,created_at timestamptz not null default now());
create table public.destinations (id uuid primary key default gen_random_uuid(),wedding_id uuid not null references public.weddings(id) on delete cascade,location_name text not null,normalized_location_name text not null,latitude double precision not null,longitude double precision not null,mapbox_place_id text,created_at timestamptz not null default now(),unique(wedding_id,normalized_location_name));
create table public.recommendations (id uuid primary key default gen_random_uuid(),wedding_id uuid not null references public.weddings(id) on delete cascade,destination_id uuid not null references public.destinations(id) on delete cascade,guest_name text not null check(length(guest_name) between 1 and 100),message text not null check(length(message) between 5 and 1500),activity_recommendation text,food_recommendation text,best_time_to_visit text,suggested_trip_length text,category text,status text not null default 'active' check(status in ('active','hidden','deleted')),created_at timestamptz not null default now());
create table public.destination_likes (id uuid primary key default gen_random_uuid(),destination_id uuid not null references public.destinations(id) on delete cascade,anonymous_session_id text not null,created_at timestamptz not null default now(),unique(destination_id,anonymous_session_id));
create table public.couple_destination_status (id uuid primary key default gen_random_uuid(),wedding_id uuid not null references public.weddings(id) on delete cascade,destination_id uuid not null references public.destinations(id) on delete cascade,status text not null default 'want_to_go' check(status in ('want_to_go','planning','visited')),planned_date date,visited_date date,couple_note text,image_url text,updated_at timestamptz not null default now(),unique(wedding_id,destination_id));
create index destinations_wedding_idx on public.destinations(wedding_id);create index recommendations_destination_idx on public.recommendations(destination_id);create index story_locations_wedding_idx on public.story_locations(wedding_id);
alter table public.weddings enable row level security;alter table public.story_locations enable row level security;alter table public.destinations enable row level security;alter table public.recommendations enable row level security;alter table public.destination_likes enable row level security;alter table public.couple_destination_status enable row level security;
create policy "public active weddings" on public.weddings for select using(status='active');create policy "owners manage weddings" on public.weddings for all using(owner_user_id=auth.uid()) with check(owner_user_id=auth.uid());
create policy "public story read" on public.story_locations for select using(exists(select 1 from public.weddings w where w.id=wedding_id and w.status='active'));create policy "owners manage story" on public.story_locations for all using(exists(select 1 from public.weddings w where w.id=wedding_id and w.owner_user_id=auth.uid()));
create policy "public destinations read" on public.destinations for select using(exists(select 1 from public.weddings w where w.id=wedding_id and w.status='active'));create policy "public destination insert" on public.destinations for insert with check(exists(select 1 from public.weddings w where w.id=wedding_id and w.status='active'));
create policy "public recommendations read" on public.recommendations for select using(status='active');create policy "public recommendations insert" on public.recommendations for insert with check(status='active' and exists(select 1 from public.weddings w where w.id=wedding_id and w.status='active'));create policy "owners manage recommendations" on public.recommendations for all using(exists(select 1 from public.weddings w where w.id=wedding_id and w.owner_user_id=auth.uid()));
create policy "public likes read" on public.destination_likes for select using(true);create policy "public likes insert" on public.destination_likes for insert with check(length(anonymous_session_id) between 10 and 100);create policy "public likes remove own" on public.destination_likes for delete using(anonymous_session_id=current_setting('request.headers',true)::json->>'x-anonymous-id');
create policy "public status read" on public.couple_destination_status for select using(true);create policy "owners manage status" on public.couple_destination_status for all using(exists(select 1 from public.weddings w where w.id=wedding_id and w.owner_user_id=auth.uid()));
